triggered := false
hold_ticks := 0
if (all(#Valve).valve_valveState ==| true) {
if (triggered == false) {
hold_ticks = hold_ticks + 1
        if (hold_ticks >= 60) {
any(#Valve).valve_close()
(#Kitchen).speaker_speak("The water valve has been closed")
            triggered = true
}
}
}
else {
triggered = false
    hold_ticks = 0
}

